const AnimatedCheckmark: React.FC<{
  progress: number;
  s: number;
  color: string;
}> = ({ progress, s, color }) => {
  const pathD = "M 28 52 L 42 66 L 72 36";
  const evolution = evolvePath(progress, pathD);

  return (
    <svg
      width={90 * s}
      height={90 * s}
      viewBox="0 0 100 100"
      style={{ overflow: "visible", transition: "none" }}
    >
      <circle
        cx="50"
        cy="50"
        r="44"
        fill="none"
        stroke={color}
        strokeWidth={6}
        style={{ transition: "none" }}
      />
      <path
        d={pathD}
        fill="none"
        stroke={color}
        strokeWidth={8}
        strokeLinecap="round"
        strokeLinejoin="round"
        strokeDasharray={evolution.strokeDasharray}
        strokeDashoffset={evolution.strokeDashoffset}
        style={{ transition: "none" }}
      />
    </svg>
  );
};

const ContentPlan: React.FC<ContentPlanProps> = ({
  backgroundColor = "#122240",
  transparentBackground = false,
  durationInSeconds = 8,
  boardColor = "#CBA374",
  paperColor = "#F5F5F5",
  textColor = "#122240",
  checkColor = "#21794B",
  title = "CONTENT PLAN",
  items = [
    {
      text: "AUTHENTIC\nFOUNDER VIDEOS",
      iconVariant: "founder",
      iconBgColor: "#A39FE1",
    },
    {
      text: "NATIVE-LOOKING\nUGC",
      iconVariant: "ugc",
      iconBgColor: "#FAD9A1",
    },
    {
      text: "EDUCATIONAL\nANIMATIONS",
      iconVariant: "education",
      iconBgColor: "#C4DFF6",
    },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Global timings
  const boardEntrance = interpolate(frame, [0, 20], [height, 0], {
    easing: Easing.out(Easing.back(1.2)),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const titleOpacity = interpolate(frame, [15, 25], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const titleY = interpolate(frame, [15, 25], [20 * s, 0], {
    easing: Easing.out(Easing.cubic),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        alignItems: "center",
        justifyContent: "center",
        fontFamily: itemFontFamily,
      }}
    >
      <div
        style={{
          position: "relative",
          width: 900 * s,
          height: 1400 * s,
          transform: `translateY(${boardEntrance}px)`,
          transition: "none",
        }}
      >
        {/* Clipboard Board */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            backgroundColor: boardColor,
            borderRadius: 40 * s,
            boxShadow: `0px ${20 * s}px ${40 * s}px rgba(0,0,0,0.3)`,
          }}
        />

        {/* Clipboard Paper */}
        <div
          style={{
            position: "absolute",
            top: 60 * s,
            bottom: 40 * s,
            left: 30 * s,
            right: 30 * s,
            backgroundColor: paperColor,
            borderRadius: 20 * s,
            boxShadow: `${10 * s}px ${10 * s}px 0px rgba(0,0,0,0.05)`,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
          }}
        >
          {/* Title */}
          <div
            style={{
              marginTop: 140 * s,
              fontSize: 90 * s,
              fontWeight: "bold",
              fontFamily: titleFontFamily,
              color: textColor,
              opacity: titleOpacity,
              transform: `translateY(${titleY}px)`,
              transition: "none",
              letterSpacing: "0.02em",
            }}
          >
            {title.toUpperCase()}
          </div>

          {/* List Items Container */}
          <div
            style={{
              marginTop: 80 * s,
              display: "flex",
              flexDirection: "column",
              gap: 70 * s,
              width: "100%",
            }}
          >
            {items.map((item, index) => {
              // Item entrance timing
              const itemStartFrame = 35 + index * 15;
              const itemOpacity = interpolate(
                frame,
                [itemStartFrame, itemStartFrame + 15],
                [0, 1],
                { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
              );
              const itemY = interpolate(
                frame,
                [itemStartFrame, itemStartFrame + 15],
                [40 * s, 0],
                {
                  easing: Easing.out(Easing.cubic),
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                }
              );

              // Tick drawing timing (sequenced after all items appear)
              const tickStartFrame = 110 + index * 25;
              const tickProgress = spring({
                frame: frame - tickStartFrame,
                fps,
                config: { damping: 14, stiffness: 120 },
              });

              return (
                <div
                  key={index}
                  style={{
                    display: "flex",
                    flexDirection: "row",
                    alignItems: "center",
                    width: 740 * s,
                    margin: "0 auto",
                    opacity: itemOpacity,
                    transform: `translateY(${itemY}px)`,
                    transition: "none",
                  }}
                >
                  {/* Left Icon Box */}
                  <div
                    style={{
                      width: 150 * s,
                      height: 150 * s,
                      borderRadius: 30 * s,
                      backgroundColor: item.iconBgColor,
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      flexShrink: 0,
                    }}
                  >
                    {item.iconVariant === "founder" && <FounderIcon s={s} />}
                    {item.iconVariant === "ugc" && <UgcIcon s={s} />}
                    {item.iconVariant === "education" && <EducationIcon s={s} />}
                  </div>

                  {/* Text */}
                  <div
                    style={{
                      flex: 1,
                      marginLeft: 40 * s,
                      fontSize: 42 * s,
                      fontWeight: 800,
                      color: textColor,
                      lineHeight: 1.2,
                      whiteSpace: "pre-wrap",
                      textTransform: "uppercase",
                    }}
                  >
                    {item.text}
                  </div>

                  {/* Right Checkmark */}
                  <div
                    style={{
                      width: 90 * s,
                      height: 90 * s,
                      flexShrink: 0,
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      marginLeft: 20 * s,
                    }}
                  >
                    <AnimatedCheckmark
                      progress={tickProgress}
                      s={s}
                      color={checkColor}
                    />
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* Clip (Hardware at top) */}
        <div
          style={{
            position: "absolute",
            top: -50 * s,
            left: "50%",
            transform: "translateX(-50%)",
            width: 320 * s,
            height: 160 * s,
            zIndex: 10,
            filter: `drop-shadow(0px ${10 * s}px ${15 * s}px rgba(0,0,0,0.25))`,
          }}
        >
          <svg
            viewBox="0 0 320 160"
            width="100%"
            height="100%"
            style={{ overflow: "visible" }}
          >
            <defs>
              <mask id="clip-hole-mask">
                <rect width="320" height="160" fill="white" />
                <circle cx="160" cy="30" r="16" fill="black" />
              </mask>
            </defs>
            <g mask="url(#clip-hole-mask)">
              {/* Clip Base Rectangle */}
              <rect
                x="20"
                y="70"
                width="280"
                height="70"
                rx="16"
                fill="#D8D8D8"
              />
              {/* Clip Top Curve */}
              <path
                d="M 100 70 L 115 15 Q 160 -15 205 15 L 220 70 Z"
                fill="#D8D8D8"
              />
              {/* Clip Base Inner Shadow/Highlight */}
              <rect
                x="20"
                y="130"
                width="280"
                height="10"
                rx="5"
                fill="#A0A0A0"
                opacity="0.5"
              />
            </g>
          </svg>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ContentPlan;